using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using Frociart;
public static class ExpressionCompatTests {
 static int checks;static void Check(bool value,string why){checks++;if(!value)throw new Exception(why);}
 static string Dec(string v){return Encoding.UTF8.GetString(Convert.FromBase64String(v));}
 static Interpreter Run(string code){var runtime=new Interpreter(FlowPseudocode.Decode(code));for(int i=0;i<1000&&runtime.State!=RuntimeState.Completed&&runtime.State!=RuntimeState.Error;i++)runtime.Step();return runtime;}
 public static int Main(string[] args){try{string root=args[0];int num=0;var conversions=new List<string>();foreach(var row in File.ReadAllLines(Path.Combine(root,"cases.tsv"))){var v=row.Split('\t');string original=Dec(v[2]),expected=Dec(v[3]),expr=original;object actual=null;bool failed=false;try{if(v[0]=="convert")expr=FlowgorithmImport.ConvertExpression(expr);actual=ExpressionLanguage.Evaluate(expr,null);}catch(ArgumentException){failed=true;}catch(FlowException){failed=true;}Check(failed==(v[1]=="error"),original+" error="+failed);if(failed)continue;Check(v[1]=="text"?actual is string:v[1]=="bool"?actual is bool:actual is double,original+" type");Check(ValueFormatter.Format(actual)==expected,original+" result "+ValueFormatter.Format(actual)+" expected "+expected);if(v[0]=="convert")conversions.Add(v[2]+"\t"+Convert.ToBase64String(Encoding.UTF8.GetBytes(expr)));
  var d=FlowPseudocode.Decode("risultato = "+expr+"\nSTAMPA risultato");for(int i=0;i<2;i++){var runtime=new Interpreter(d);for(int n=0;n<15&&runtime.State!=RuntimeState.Completed&&runtime.State!=RuntimeState.Error;n++)runtime.Step();Check(runtime.State==RuntimeState.Completed&&runtime.Output.Single()==expected,"graph/codec execution "+original);d=DiagramIO.DecodeDocument(DiagramIO.EncodeDocument(FlowPseudocode.Decode(FlowPseudocode.Encode(d))));}File.WriteAllBytes(Path.Combine(root,"fixtures","expr-"+(num++).ToString("D3")+".frociart"),DiagramIO.EncodeDocument(d));
 }
 var vars=new Dictionary<string,object>(StringComparer.OrdinalIgnoreCase){{"mod",7d},{"model",11d},{"mod5",13d},{"large",new String('x',32768)}};
 foreach(var pair in new[]{new[]{"mod + 1","8"},new[]{"mod mod 5","2"},new[]{"model + mod5","24"},new[]{"2 * mod","14"}})Check(ValueFormatter.Format(ExpressionLanguage.Evaluate(pair[0],vars))==pair[1],"Legacy identifier "+pair[0]);
 Check(((string)ExpressionLanguage.Evaluate("large & \"\"",vars)).Length==32768,"concat exact string boundary");bool overflow=false;try{ExpressionLanguage.Evaluate("large & 1",vars);}catch(FlowException){overflow=true;}Check(overflow,"concat rejects string overflow");
 Check(ValueFormatter.Format(ExpressionLanguage.Evaluate("-2^2",null))=="-4"&&ValueFormatter.Format(ExpressionLanguage.Evaluate("2^3^2",null))=="512","Legacy power semantics unchanged");
 Check(new HashSet<string>(ExpressionLanguage.GetVariables("mod mod model & mod5")).SetEquals(new[]{"mod","model","mod5"}),"Contextual mod variable references");
 string functions="FUNZIONE mod(x: REALE) -> REALE r\nr = x × 2\nFINE FUNZIONE\nSTAMPA mod(3) & mod(4)\nSTAMPA 17 mod mod(2)";
 var fdoc=FlowPseudocode.Decode(functions);var catalog=FunctionModel.Catalog(fdoc);string converted=FlowgorithmImport.ConvertExpression("mod(3) & mod(4)",catalog);Check(converted.Contains("mod(3)")&&converted.Contains("mod(4)"),"Passive project function conversion");var r=Run(functions);Check(r.State==RuntimeState.Completed&&r.Output.SequenceEqual(new[]{"68","1"}),"User function named mod and concat order");File.WriteAllBytes(Path.Combine(root,"fixtures","expr-functions.frociart"),DiagramIO.EncodeDocument(fdoc));
 foreach(string code in new[]{"STAMPA 1 & 2","DICHIARA x: TESTO\nx = 1 & 2\nSTAMPA x","STAMPA \"Resto: \" & 2","STAMPA 17 mod 5","STAMPA 3 ≤ 5"}){var d=FlowPseudocode.Decode(code);var export=FlowgorithmExport.Analyze(d);Check(export.CanExport,"FPRG export accepts "+code+" "+String.Join(";",export.Issues.Select(i=>i.Message)));var copy=new Interpreter(FlowgorithmImport.DecodeText(export.Xml));while(copy.State!=RuntimeState.Completed&&copy.State!=RuntimeState.Error)copy.Step();Check(copy.State==RuntimeState.Completed&&copy.Output.SequenceEqual(Run(code).Output),"FPRG scalar roundtrip "+code);}
 foreach(string bad in new[]{new String('(',49)+"1"+new String(')',49),new String('1',8193),String.Join("+",Enumerable.Repeat("1",600))}){bool rejected=false;try{FlowgorithmImport.ConvertExpression(bad);}catch(ArgumentException){rejected=true;}catch(FlowException){rejected=true;}Check(rejected,"Bounded passive conversion");}
 File.WriteAllLines(Path.Combine(root,"converted-pc.tsv"),conversions,new UTF8Encoding(false));Console.WriteLine("EXPRESSION_COMPAT_PC PASS checks="+checks+" generated fixtures="+(num+1));return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
